841	// saveToFile saves settings to the specified file path.
842	func saveToFile(ctx context.Context, settings *EntireSettings, filePath string) error {
843		// Get absolute path for the file
844		filePathAbs, err := paths.AbsPath(ctx, filePath)
845		if err != nil {
846			filePathAbs = filePath // Fallback to relative
847		}
848	
849		// Ensure directory exists
850		dir := filepath.Dir(filePathAbs)
851		if err := os.MkdirAll(dir, 0o750); err != nil {
852			return fmt.Errorf("creating settings directory: %w", err)
853		}
854	
855		data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
856		if err != nil {
857			return fmt.Errorf("marshaling settings: %w", err)
858		}
859	
860		//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
861		if err := os.WriteFile(filePathAbs, data, 0o644); err != nil {
862			return fmt.Errorf("writing settings file: %w", err)
863		}
864		return nil
865	}
