// only via v2 refs, with no v1 dual-write. This is the case when
// strategy_options.checkpoints_version is set to 2.
func (s *EntireSettings) IsCheckpointsV2OnlyEnabled() bool {
	return s.CheckpointsVersion() == 2
}

